using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace SirAgent.Core.Tests;

/// <summary>
/// Same results as the Node agent on the files of `riferimento-node.json` (generated by
/// `riferimento/genera-riferimento.ts` from the example `packages/dvw-parser/test/fixtures/partita.dvw`):
/// decoding, header and scout lines, matchKey, suspicion, planned requests and content hash.
/// </summary>
public sealed class RiferimentoNodeTests
{
    private static readonly JsonElement Reference = JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "riferimento-node.json"))).RootElement;

    public static TheoryData<string> Cases()
    {
        var data = new TheoryData<string>();
        foreach (var c in Reference.GetProperty("cases").EnumerateArray()) data.Add(c.GetProperty("name").GetString()!);
        return data;
    }

    private static JsonElement Case(string name) =>
        Reference.GetProperty("cases").EnumerateArray().Single(c => c.GetProperty("name").GetString() == name);

    private static string Sha(string s) => Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(s)));

    [Fact]
    public void Il_riferimento_parte_dal_file_di_esempio_del_repository()
    {
        var original = File.ReadAllBytes(Path.Combine(Repo.Root, "packages", "dvw-parser", "test", "fixtures", "partita.dvw"));
        Assert.Equal(Convert.ToBase64String(original), Case("originale-windows-1252").GetProperty("bytesBase64").GetString());
        Assert.True(Reference.GetProperty("cases").GetArrayLength() >= 15);
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void Lettura_chiave_e_sospetto_uguali_al_Node(string name)
    {
        var c = Case(name);
        var bytes = Convert.FromBase64String(c.GetProperty("bytesBase64").GetString()!);
        Assert.Equal(c.GetProperty("bytesHash").GetString(), Dvw.BytesHash(bytes));
        var read = Dvw.Read(bytes);
        if (c.TryGetProperty("incomplete", out var reason))
        {
            Assert.Equal(reason.GetString(), Assert.IsType<DvwRead.Incomplete>(read).Reason);
            return;
        }
        var content = Assert.IsType<DvwRead.Content>(read);
        Assert.Equal(c.GetProperty("header").GetString(), content.Value.Header);
        Assert.Equal(c.GetProperty("headerSha256").GetString(), Sha(content.Value.Header));
        Assert.Equal(c.GetProperty("lines").EnumerateArray().Select(l => l.GetString()!).ToList(), content.Value.Lines);
        Assert.Equal(c.GetProperty("endsWithNewline").GetBoolean(), content.EndsWithNewline);
        Assert.Equal(c.GetProperty("matchKey").GetString(), Dvw.DeriveMatchKey(content.Value.Header, c.GetProperty("filePath").GetString()!));
        var suspicion = c.GetProperty("suspicionWithoutBase");
        Assert.Equal(suspicion.ValueKind == JsonValueKind.Null ? null : suspicion.GetString(), Dvw.Suspicion(content, null));
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void Richieste_pianificate_e_hash_uguali_al_Node(string name)
    {
        var c = Case(name);
        if (!c.TryGetProperty("plans", out var plans)) return;
        var content = ((DvwRead.Content)Dvw.Read(Convert.FromBase64String(c.GetProperty("bytesBase64").GetString()!))).Value;
        var maxLines = c.GetProperty("maxLines").ValueKind == JsonValueKind.Number ? c.GetProperty("maxLines").GetInt32() : Contract.IngestMaxLines;
        var lines = content.Lines;
        var bases = new Dictionary<string, DvwContent?>
        {
            ["nessuna"] = null,
            ["prefisso"] = new(content.Header, lines.Take(Math.Max(0, lines.Count - 3)).ToList()),
            ["uguale"] = new(content.Header, lines),
            ["headerCambiato"] = new(content.Header + "X", lines),
            ["rigaCambiata"] = new(content.Header, lines.Select((l, i) => i == 1 ? l + "~" : l).ToList()),
            ["piuLunga"] = new(content.Header, [.. lines, "riga in più"]),
        };
        foreach (var (baseName, baseContent) in bases)
        {
            foreach (var force in new[] { false, true })
            {
                var expected = plans.GetProperty(baseName + (force ? "+forza" : ""));
                var s = expected.GetProperty("suspicion");
                Assert.Equal(s.ValueKind == JsonValueKind.Null ? null : s.GetString(), Dvw.Suspicion(new DvwRead.Content(content, true), baseContent));
                var planned = ScoutSync.PlanRequests(baseContent, content, force, maxLines);
                var wanted = expected.GetProperty("requests").EnumerateArray().ToList();
                Assert.Equal(wanted.Count, planned.Count);
                for (var i = 0; i < planned.Count; i++)
                {
                    var w = wanted[i];
                    var p = planned[i];
                    var where = $"{name} {baseName} forza={force} #{i}";
                    Assert.True(w.GetProperty("kind").GetString() == p.Kind, where);
                    Assert.True(w.GetProperty("fromIndex").GetInt32() == p.FromIndex, where);
                    Assert.True(w.GetProperty("lineCount").GetInt32() == p.Lines.Count, where);
                    Assert.True(w.GetProperty("linesSha256").GetString() == Sha(string.Join('\n', p.Lines)), where);
                    var header = w.GetProperty("headerSha256");
                    Assert.True((header.ValueKind == JsonValueKind.Null ? null : header.GetString()) == (p.Header is null ? null : Sha(p.Header)), where);
                    Assert.True(w.GetProperty("contentHash").GetString() == p.ContentHash, where);
                }
            }
        }
    }

    [Fact]
    public void Windows1252_come_iconv_lite_anche_sui_byte_non_definiti()
    {
        byte[] bytes = [0x80, 0x81, 0x8D, 0x8F, 0x90, 0x9D, 0x9F, 0xE0, 0x41];
        // invalid UTF-8: decoded as Windows-1252
        Assert.Equal("€�����ŸàA", DvwDecoder.Decode(bytes));
    }

    [Fact]
    public void Utf8_valido_senza_bom_resta_utf8()
    {
        Assert.Equal("Città", DvwDecoder.Decode(Encoding.UTF8.GetBytes("Città")));
        Assert.Equal("ok", DvwDecoder.Decode([0xEF, 0xBB, 0xBF, (byte)'o', (byte)'k']));
    }

    [Fact]
    public void Hash_delle_righe_come_hashScoutLines()
    {
        // sha256("") and sha256("a\nb")
        Assert.Equal("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", ScoutSync.HashScoutLines([]));
        Assert.Equal(Sha("a\nb"), ScoutSync.HashScoutLines(["a", "b"]));
    }
}
